statements.text:
create table if not exists public.mapping_import_batches (
  import_batch_id uuid primary key default gen_random_uuid(),
  source_channel text not null,
  source_file_name text not null,
  source_sheet_name text not null,
  expected_row_count integer not null default 0,
  imported_row_count integer not null default 0,
  import_status text not null default 'importing',
  file_sha256 text null,
  note text null,
  created_at timestamptz not null default now(),
  completed_at timestamptz null,
  constraint mapping_import_batches_status_chk check (import_status in ('importing','completed','failed'))
);

create table if not exists public.channel_sku_mappings (
  mapping_id bigint generated by default as identity primary key,
  import_batch_id uuid not null references public.mapping_import_batches(import_batch_id) on delete restrict,
  source_channel text not null,
  sellpia_sku_code text not null,
  channel_code text not null,
  channel_product_code text null,
  channel_option_code text null,
  match_tier text null,
  match_score numeric null,
  source_row_no integer not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint channel_sku_mappings_channel_chk check (source_channel in ('smartstore','ably','makeshop')),
  constraint channel_sku_mappings_batch_row_uniq unique (import_batch_id, source_row_no)
);

create index if not exists ix_channel_sku_mappings_active_channel_sku
  on public.channel_sku_mappings (source_channel, sellpia_sku_code)
  where is_active = true;
create index if not exists ix_channel_sku_mappings_active_channel_code
  on public.channel_sku_mappings (source_channel, channel_product_code, channel_option_code)
  where is_active = true;
create index if not exists ix_channel_sku_mappings_batch
  on public.channel_sku_mappings (import_batch_id, source_row_no);

alter table public.mapping_import_batches enable row level security;
alter table public.channel_sku_mappings enable row level security;

drop policy if exists "mapping import batches readable" on public.mapping_import_batches;
create policy "mapping import batches readable" on public.mapping_import_batches
for select to anon, authenticated using (true);

drop policy if exists "channel sku mappings readable" on public.channel_sku_mappings;
create policy "channel sku mappings readable" on public.channel_sku_mappings
for select to anon, authenticated using (true);

create or replace view public.channel_sku_mappings_active as
select m.*, b.source_file_name, b.source_sheet_name, b.import_status, b.completed_at
from public.channel_sku_mappings m
join public.mapping_import_batches b using (import_batch_id)
where m.is_active = true and b.import_status = 'completed';

grant select on public.mapping_import_batches to anon, authenticated;
grant select on public.channel_sku_mappings to anon, authenticated;
grant select on public.channel_sku_mappings_active to anon, authenticated;
